// Australian/British and American spellings are both accepted, as in the real test.
function spell(w){return String(w).toLowerCase().replace(/ise(s|d)?$/,'ize$1').replace(/ising$/,'izing').replace(/isation(s?)$/,'ization$1').replace(/our(s?)$/,'or$1').replace(/elling$/,'eling').replace(/elled$/,'eled').replace(/ellor(s?)$/,'elor$1').replace(/lled$/,'led').replace(/mme(s?)$/,'m$1').replace(/tre(s?)$/,'ter$1').replace(/ence$/,'ense').replace(/ogue(s?)$/,'og$1').replace(/yse(s|d)?$/,'yze$1').replace(/ysing$/,'yzing').replace(/([^l])lment(s?)$/,'$1llment$2');}
