// ---------- AI marking with Pearson-style double marking ----------
const RUBRIC={
 FLU:'Oral fluency 0 to 5: 5 smooth rhythm and phrasing, no hesitations, repetitions or false starts; 4 acceptable rhythm, at most one hesitation, repetition or false start; 3 acceptable speed, possibly uneven, more than one hesitation but mostly continuous phrases, no long pauses; 2 uneven or staccato, a few disruptions, at most one long pause; 1 irregular phrasing, multiple hesitations or false starts; 0 slow and laboured, mostly isolated words.',
 PRON:'Pronunciation 0 to 5: 5 all sounds easily understood, natural stress; 4 clear, a few minor distortions; 3 most sounds correct, a few words unclear; 2 at least two-thirds intelligible, some sounds consistently wrong; 1 about a third of words could be missed; 0 more than half unintelligible.',
 DI:'Content 0 to 6: 6 full, accurate description of all key elements and their relationships, with interpretation or implication, precise varied vocabulary, a listener could picture the image; 5 main features accurate, some relationships, minor details missing or slightly wrong; 4 simple accurate description with basic relationships, main features not fully covered, some repetition; 3 mainly superficial, minor inaccuracies, narrow vocabulary, elements not described as a whole; 2 minimal superficial description with inaccuracies; 1 disconnected list of elements with no elaboration; 0 too limited, irrelevant, or memorised material.',
 RL:'Content 0 to 6: 6 clear, accurate, full comprehension, main ideas paraphrased with specific detail, ideas logically connected; 5 main ideas and some details accurate, minor inconsistencies, good connectives; 4 some main ideas and details, possible inaccuracies or focus on minor points, weak connections; 3 some ideas, not fully accurate, irrelevant content or unreformulated repetition, mainly unconnected; 2 mostly inaccurate or incomplete, main ideas missed; 1 repeats isolated words or phrases without communicating meaning; 0 too limited, irrelevant, or memorised.',
 RTS:'Content 0 to 6: 6 fully achieves the communicative goal with full attention to context, persuasive, flexible and precise, going beyond the prompt\'s language; 5 adequately achieves the goal with only minor omissions, clear and accurate; 4 partially achieves the goal with some omissions, minor inaccuracies; 3 achieves only the most basic goal, functional but limited, some inappropriate elements (tone, register); 2 relevant but does not achieve the goal, relies heavily on prompt language; 1 repeats isolated prompt words or minimally addresses the prompt; 0 too limited, irrelevant, or memorised.',
 SGD:'Content 0 to 6: 6 full comprehension, each speaker\'s contribution paraphrased with detail, different perspectives synthesised effectively; 5 main ideas and some details of each speaker, partial synthesis, some ideas underrepresented; 4 main ideas and some details but focuses on individual views rather than relationships between them; 3 some ideas, may miss the overall direction, mainly unconnected; 2 mostly inaccurate or incomplete, irrelevant or repeated language; 1 isolated words or phrases; 0 too limited, irrelevant, or memorised.',
 SUM:'Content 0 to 4: 4 comprehensive summary showing full comprehension, effective paraphrase, extraneous detail removed, concise and coherent; 3 adequate summary, inconsistent paraphrase, minor omissions, less efficient synthesis; 2 partial summary, main points not distinguished from detail, relies heavily on excerpts from the source; 1 relevant but not meaningfully summarised, disconnected ideas, main ideas omitted or misrepresented; 0 too limited, no comprehension, or misrepresents the topic or purpose.',
 SHORTGV:'Grammar 0 to 2: 2 correct grammatical structure; 1 errors that do not hinder communication; 0 defective structure that could hinder communication. Vocabulary 0 to 2: 2 appropriate word choice; 1 some lexical errors without hindering communication; 0 defective word choice that could hinder communication. Spelling (SST only) 0 to 2: 2 no errors, 1 one error, 0 more than one.',
 WE:'Content 0 to 6: 6 fully addresses the prompt in depth, argument convincingly supported with relevant examples; 5 adequately addresses the prompt, persuasive argument, main points highlighted with minor exceptions; 4 addresses the main point, argument generally convincing but lacks depth, inconsistent support; 3 relevant but does not adequately address the main points, supporting detail often missing or inappropriate; 2 superficial, generic statements or repetition of the prompt, few supporting details; 1 incomplete understanding of the prompt, disjointed support; 0 does not properly deal with the prompt, including essays relying significantly on memorised or pre-prepared material. Development, structure and coherence 0 to 6: 6 effective logical structure that flows smoothly, clear argument, well-developed introduction and conclusion, varied connectives; 5 conventional logical structure, clear argument, some points developed at length, some abrupt transitions; 4 mostly conventional structure, some elements missing or poorly linked, some ideas hard to follow; 3 traces of structure but mainly simple or disconnected points, position present but underdeveloped; 2 little recognisable structure, simple linking words only; 1 disconnected ideas, no clear position; 0 no recognisable structure. Grammar 0 to 2: 2 consistent control of complex language, rare errors; 1 relatively high control, no errors that cause misunderstanding; 0 mainly simple structures or several basic mistakes. General linguistic range 0 to 6: 6 varied expression used with ease and precision, rare minor errors; 5 varied expression used appropriately, occasional errors; 4 sufficient range for basic ideas, limitations with complex ideas causing repetition or circumlocution; 3 narrow range, simple expressions repeated, errors cause some disruption; 2 limited vocabulary, frequent breakdowns; 1 highly restricted, pervasive errors; 0 meaning not accessible. Vocabulary range 0 to 2: 2 broad lexical repertoire including idiomatic expressions; 1 good range for academic topics with some imprecision; 0 mainly basic vocabulary. Spelling 0 to 2: 2 no errors, 1 one error, 0 more than one.'};
const RULES='template_share_percent is the share of words that are common generic template phrases. Short connectors are fine; but when generic phrasing carries the response and topic-specific content is thin, Content must drop accordingly (and is 0 if the response is essentially a memorised template). Scoring rules from the official Score Guide: Content is scored first. If Content is 0 (no response, irrelevant, too limited, or memorised or pre-prepared material that is not about this prompt), no other trait is scored and the response earns 0. Long generic template phrases that could fit any prompt are treated as memorised material: they earn no credit and, if they make up most of the response, Content is 0. Paraphrase in the candidate\'s own words is rewarded; copying long chunks of the prompt or source is penalised.';
function tplText(types){return types.filter(t=>window.TPL&&TPL[t]).map(t=>t+': '+TPL[t].versions.map(v=>v[0]+' -> '+v[1]).join(' | ')+' ('+TPL[t].check+')').join('\n');}
const TPL_RULE='STUDENT TEMPLATES: the student practises with the fill-in templates below. They are short linking frames, consistent with Pearson guidance as long as every slot is filled with ideas from this question: give the frame words themselves no credit and no penalty, and judge the content in the slots. Long generic sentences that carry no question-specific content still count as memorised material. Your "better" version MUST follow the matching template (pick the best version for this passage), filling every slot with content from this question in fresh words. Also return "template_fill": one entry per slot, in order: {"slot":"TOPIC","yours":"the words from the response that fill this slot, or empty string if missing","better":"a stronger filler for this slot"}.\n';
function speakPrompt(sp,rater){return 'You are PTE Academic content rater '+rater+'. Mark each spoken response strictly against the official PTE Academic rubric below. Mark independently and do not be generous.\n\nIMPORTANT: you only see a speech-to-text transcript of the candidate. Pearson scores Oral Fluency and Pronunciation from audio, so give them as careful ESTIMATES using the evidence provided: "signals" counts hesitation sounds (and, when present, audio_measured_from_microphone gives the real start delay, pause counts and speaking time from the recording: weight it heavily for Oral Fluency), repetitions and false starts and gives words per second (fluent speech is roughly 2 to 2.6 words per second over the time limit); words that look wrongly transcribed (nonsense or wrong words in an otherwise sensible sentence) suggest unclear pronunciation.\n\n'+RULES+'\n\nRUBRICS\nDI '+RUBRIC.DI+'\nRL '+RUBRIC.RL+'\nRTS '+RUBRIC.RTS+'\nSGD '+RUBRIC.SGD+'\n'+RUBRIC.FLU+'\n'+RUBRIC.PRON+'\nTask notes: DI must describe the actual data (penalise invented or wrong figures). RTS must be spoken directly to the person with suitable tone. SGD must cover every speaker and how their views relate.\n\n'+TPL_RULE+tplText(['RL','SGD'])+'\nFor DI and RTS (no student template), return template_fill using these slots: DI: INTRODUCTION, KEY FIGURE 1, KEY FIGURE 2, COMPARISON OR TREND, CONCLUSION. RTS: GREETING, SITUATION, REASON OR APOLOGY, SOLUTION OR REQUEST, POLITE CLOSE.\nWrite feedback in clear, simple English for an Australian university student. Do not use em dashes or en dashes.\nReturn ONLY JSON: {"results":[{"id":"...","content":0,"content_reason":"which rubric level fits and why, one sentence","fluency":0,"pronunciation":0,"summary":"one sentence verdict","strengths":["..."],"fixes":["specific and actionable; quote their words where useful"],"pron_flags":["words that look mis-transcribed"],"edits":[{"original":"exact words from the transcript","improved":"a better way to say it","why":"what it adds: missing key point, clearer linking, more precise word, stronger conclusion"}],"template_fill":[{"slot":"TOPIC","yours":"...","better":"..."}],"better":"an improved version of THEIR answer that keeps their ideas, applies all the edits, follows the student template where one exists, natural spoken English, right length for the time limit"}]}\nEDITS: give at least 4 concrete phrase-level edits to the transcript, including where to add any missing key point (quote the words it should follow).\n\nITEMS:\n'+JSON.stringify(sp.map(x=>({id:x.item.id,type:x.item.type,time_limit_seconds:T[x.item.type].rec,prompt:material(x.item),transcript:respText(x.resp)||'(no speech captured)',signals:Object.assign(signals(respText(x.resp),T[x.item.type].rec),x.resp&&x.resp.audio?{audio_measured_from_microphone:x.resp.audio}:{})})));}
function writePrompt(wr,rater){return 'You are PTE Academic writing rater '+rater+'. Mark each written response strictly against the official PTE Academic rubric below. Mark independently and do not be generous. Form has ALREADY been scored by the app and is given to you; do not score it.\n\n'+RULES+'\n\nRUBRICS\nSWT (one-sentence summary of a passage): '+RUBRIC.SUM+' '+RUBRIC.SHORTGV+'\nSST (50 to 70 word summary of a lecture): same Content scale as SWT, plus Grammar, Vocabulary and Spelling as above.\nWE (essay): '+RUBRIC.WE+'\n\nTrait names to use exactly: SWT: Content, Grammar, Vocabulary. SST: Content, Grammar, Vocabulary, Spelling. WE: Content, Development, structure and coherence, Grammar, General linguistic range, Vocabulary range, Spelling.\n'+TPL_RULE+tplText(['SWT','SST','WE'])+'\nFor WE, template_fill slots are: TOPIC, SIDE A, SIDE B, POSITION, POINT 1, EXPLAIN, EXAMPLE, POINT 2, OTHER SIDE POINT, EFFECT, OTHER SIDE EXAMPLE, CONCLUSION, RECOMMENDATION.\nFeedback must be specific, kind and practical, in simple English for an Australian university student. Do not use em dashes or en dashes.\nReturn ONLY JSON: {"results":[{"id":"...","traits":{"Content":0,"...":0},"content_reason":"which rubric level fits and why, one sentence","summary":"one sentence verdict","strengths":["..."],"fixes":["..."],"edits":[{"original":"exact words copied from the response","improved":"the rewritten wording","why":"what it fixes and which trait it lifts (grammar, vocabulary, coherence, content, spelling, form)"}],"template_fill":[{"slot":"TOPIC","yours":"...","better":"..."}],"better":"an improved version of THEIR response that keeps their ideas, applies all the edits, follows the student template, and obeys the task length rules"}]}\nEDITS: go through the response sentence by sentence and list every concrete change that would raise the score: grammar and spelling errors, informal or vague words to replace with precise academic ones, missing linking words, sentences to combine or split, and missing key ideas to add (quote the place where they should go). Give at least 8 edits for an essay and at least 3 for a summary unless the response is genuinely near-perfect. Quote the original words exactly so they can be found in the text.\n\nITEMS:\n'+JSON.stringify(wr.map(x=>({id:x.item.id,type:x.item.type,prompt:material(x.item),response:respText(x.resp)||'(empty)',form:formOf(x.item.type,respText(x.resp)),template_share_percent:templateShare(respText(x.resp)).pct})));}
// Traits that Pearson double-marks (AI plus human): Content on all seven open tasks, plus two essay traits
function reviewed(type){return type==='WE'?['Content','Development, structure and coherence','General linguistic range']:['Content'];}
function getT(type,r,k){if(!r)return null;if(SPEAK_OPEN.has(type))return k==='Content'?+r.content:null;const tr=r.traits||{};const key=Object.keys(tr).find(x=>x.toLowerCase()===k.toLowerCase())||Object.keys(tr).find(x=>x.toLowerCase().startsWith(k.toLowerCase().slice(0,8)));return key!=null?+tr[key]:null;}
function setT(type,r,k,v){if(SPEAK_OPEN.has(type)){if(k==='Content')r.content=v;return;}r.traits=r.traits||{};const key=Object.keys(r.traits).find(x=>x.toLowerCase()===k.toLowerCase())||k;r.traits[key]=v;}
async function rateAll(sp,wr,rater){const jobs=[];if(sp.length)jobs.push(ask(speakPrompt(sp,rater),'default'));if(wr.length)jobs.push(ask(writePrompt(wr,rater),'default'));const outs=await Promise.all(jobs);const map={};outs.forEach(o=>(o&&o.results||[]).forEach(r=>{if(r&&r.id)map[r.id]=r;}));return map;}
async function aiMark(list,onStep){const sp=list.filter(x=>SPEAK_OPEN.has(x.item.type)),wr=list.filter(x=>!SPEAK_OPEN.has(x.item.type));const dbl=DB.settings.double!==false;
 onStep&&onStep(dbl?'Two independent raters are marking your answers...':'Marking your answers...');
 const runs=dbl?await Promise.all([rateAll(sp,wr,'A'),rateAll(sp,wr,'B').catch(()=>({}))]):[await rateAll(sp,wr,'A')];
 const A=runs[0],Bm=runs[1]||{};const out={};const disputes=[];
 list.forEach(({item})=>{let a=A[item.id],b=Bm[item.id];if(!a&&b){a=b;b=null;}if(!a)return;const fin=clone(a);fin._double={};
  if(b)reviewed(item.type).forEach(k=>{const va=getT(item.type,a,k),vb=getT(item.type,b,k);if(va==null||vb==null||isNaN(va)||isNaN(vb))return;if(Math.abs(va-vb)<=1){const v=Math.round((va+vb)/2*2)/2;setT(item.type,fin,k,v);fin._double[k]={a:va,b:vb,final:v};}else{fin._double[k]={a:va,b:vb,final:null};disputes.push({id:item.id,item,trait:k,a:va,b:vb,ra:a.content_reason||'',rb:b.content_reason||''});}});
  out[item.id]=fin;});
 if(disputes.length){onStep&&onStep('The raters disagreed on '+disputes.length+' score(s). A senior rater is deciding...');
  try{const res=await ask('You are a senior PTE Academic rater. Two raters disagreed by 2 or more points on the traits below. Using the official rubric, decide the final score for each. '+RULES+'\nRUBRICS\nDI '+RUBRIC.DI+'\nRL '+RUBRIC.RL+'\nRTS '+RUBRIC.RTS+'\nSGD '+RUBRIC.SGD+'\nSWT/SST '+RUBRIC.SUM+'\nWE '+RUBRIC.WE+'\nReturn ONLY JSON: {"decisions":[{"id":"...","trait":"...","score":0,"reason":"one sentence"}]}\n\nDISPUTES:\n'+JSON.stringify(disputes.map(d=>({id:d.id,type:d.item.type,trait:d.trait,rater_A:d.a,rater_A_reason:d.ra,rater_B:d.b,rater_B_reason:d.rb,prompt:material(d.item),response:respText(list.find(x=>x.item.id===d.id).resp)}))),'default');
   (res.decisions||[]).forEach(dc=>{const f=out[dc.id];if(!f)return;const it=list.find(x=>x.item.id===dc.id).item;setT(it.type,f,dc.trait,+dc.score);if(f._double[dc.trait])Object.assign(f._double[dc.trait],{final:+dc.score,adj:true});if(dc.trait==='Content'&&dc.reason)f.content_reason='Senior rater: '+dc.reason;});}catch(e){}
  disputes.forEach(d=>{const f=out[d.id];const x=f._double[d.trait];if(x&&x.final==null){x.final=Math.round((x.a+x.b)/2*2)/2;setT(d.item.type,f,d.trait,x.final);}});}
 return out;}
function material(item){switch(item.type){case 'DI':return'Chart: '+JSON.stringify(item.chart);case 'RL':case 'SST':return'Lecture transcript: '+item.text;case 'RTS':return'Situation: '+item.situation;case 'SGD':return'Discussion on "'+item.topic+'": '+item.turns.map(t=>'Speaker '+t.speaker+': '+t.text).join(' ');case 'SWT':return'Passage: '+item.text;case 'WE':return'Essay prompt: '+item.prompt;}return'';}
function dblNote(d,k){const x=d&&d[k];if(!x)return'';return' · Double-marked: '+x.a+' and '+x.b+(x.adj?', decided by senior rater':'')+' → '+x.final;}
function fromAI(item,resp,a){const t=item.type;const text=respText(resp);
 if(SPEAK_OPEN.has(t)){const c=clamp(+a.content||0,0,6);const gate=c===0;const f=gate?0:clamp(Math.round(+a.fluency||0),0,5),p=gate?0:clamp(Math.round(+a.pronunciation||0),0,5);
  return{got:c+f+p,max:16,pct:(c+f+p)/16,traits:[{name:'Content',score:c,max:6,comment:lvl(t,c)+dblNote(a._double,'Content')},{name:'Oral fluency (estimate)',score:f,max:5,comment:gate?'Not scored because Content is 0':lvl('FLU',f)},{name:'Pronunciation (estimate)',score:p,max:5,comment:gate?'Not scored because Content is 0':lvl('PRON',p)}],summary:a.summary,why:a.content_reason,strengths:a.strengths||[],fixes:(gate?['Content scored 0, so (as in the real test) nothing else was scored.']:[]).concat(a.fixes||[]),pron:gate?[]:(a.pron_flags||[]),edits:a.edits||[],tfill:a.template_fill||[],better:a.better,model:item.model};}
 const form=formOf(t,text);const traits=WTRAITS[t].map(([nm,mx])=>{if(nm==='Form')return{name:nm,score:form.score,max:mx,comment:form.note};const v=getT(t,a,nm);const sc=clamp(+v||0,0,mx);let cm=nm==='Content'&&t!=='WE'?lvl('SUM',sc):'';cm+=dblNote(a._double,nm);return{name:nm,score:sc,max:mx,comment:cm.replace(/^ · /,'')};});
 const content=traits[0].score;const gate=form.score===0||content===0;let got=traits.reduce((s,x)=>s+x.score,0),max=traits.reduce((s,x)=>s+x.max,0);if(gate)got=0;
 return{got,max,pct:max?got/max:0,traits,summary:a.summary,why:a.content_reason,strengths:a.strengths||[],fixes:(form.score===0?['Form rule broken ('+form.note+'). In the real test this response scores 0.']:content===0?['Content scored 0, so (as in the real test) the whole response scores 0.']:[]).concat(a.fixes||[]),edits:a.edits||(a.errors||[]).map(e=>({original:e.original,improved:e.correction,why:e.why})),tfill:a.template_fill||[],better:a.better,model:item.model};}

// ---------- skill scores: points-weighted, IELTS concordance (Pearson, July 2025) ----------
const CONC={Overall:[24,31,39,47,55,63,71,79,86],Listening:[26,33,40,47,53,58,64,69,75],Reading:[29,36,42,48,54,59,65,70,75],Speaking:[14,24,39,54,66,76,83,88,91],Writing:[17,29,41,51,60,69,77,85,91]};
function ielts(skill,score){const b=CONC[skill];if(!b)return'';if(score<b[0])return'below 4.5';let band=4.5;for(let i=0;i<b.length;i++){if(score>=b[i])band=4.5+i*0.5;}return band>=8.5?'8.5 or above':String(band);}
function skillScores(items,res){const sk={Listening:[0,0],Reading:[0,0],Speaking:[0,0],Writing:[0,0]};items.forEach(it=>{const r=res[it.id];if(!r||!r.max)return;T[it.type].skills.forEach(s=>{sk[s][0]+=r.got;sk[s][1]+=r.max;});});
 const scores={};Object.keys(sk).forEach(k=>{if(sk[k][1])scores[k]=Math.round(10+80*sk[k][0]/sk[k][1]);});const v=Object.values(scores);if(v.length)scores.Overall=Math.round(v.reduce((a,b)=>a+b,0)/v.length);return scores;}

// ---------- shell & navigation ----------
const app=$('#app');
function setView(html,examMode){app.innerHTML=html;document.body.classList.toggle('exam',!!examMode);$('#capPanel').hidden=true;window.scrollTo(0,0);}
const NAV=[['home','Home'],['plan','My 5-day plan'],['mock','Mock test'],['practice','Practice'],['tips','Tips'],['templates','Templates'],['resources','Free resources'],['progress','Progress'],['settings','Settings']];
function renderNav(active){$('#nav').innerHTML=NAV.map(([k,l])=>'<a href="#'+k+'" data-k="'+k+'" class="'+(k===active?'on':'')+'">'+l+'</a>').join('');$$('#nav a').forEach(a=>a.onclick=e=>{e.preventDefault();go(a.dataset.k);});}
document.addEventListener('click',e=>{const a=e.target.closest&&e.target.closest('a[href^="#"]');if(a&&!a.closest('#nav')){const h=a.getAttribute('href').slice(1);if(h&&location.hash==='#'+h){e.preventDefault();route();}}});
function route(){LAST_VIEW=null;const h=(location.hash||'#home').slice(1);const v=h.split('-')[0];newRun();
 if(v==='plan')return viewPlan();if(v==='export')return viewExport();if(v==='import')return viewImport();if(v==='mock')return viewMockStart();if(v==='practice')return viewPractice();if(v==='tips')return viewTips();if(v==='templates')return viewTemplates();if(v==='resources')return viewResources();if(v==='progress')return viewProgress();if(v==='settings')return viewSettings();return viewHome();}
window.addEventListener('hashchange',route);
function go(h){if(location.hash==='#'+h)route();else location.hash=h;}

