 const mocks=DB.mocks.slice().reverse().map(m=>'<tr><td>'+new Date(m.t).toLocaleDateString('en-AU',{day:'numeric',month:'short'})+'</td><td>'+esc(m.scope)+'</td>'+['Overall','Listening','Reading','Speaking','Writing'].map(k=>'<td>'+(m.scores[k]!=null?m.scores[k]:'-')+'</td>').join('')+'</tr>').join('');
