let MOCK=null;
function viewMockStart(){renderNav('mock');const aiOk=AI==='ready';
 setView('<section class="card"><h1>Mock test</h1><p>The mock follows the real order and timing: Part 1 Speaking and Writing (each item individually timed), Part 2 Reading (shared clock), Part 3 Listening. Audio plays once. You get an estimated score report with feedback on every answer at the end.</p>'+
 '<h3>1. Choose the paper</h3><label class="opt"><input type="radio" name="msrc" value="ai" '+(aiOk?'checked':'disabled')+'> <span><b>New AI-generated paper</b>: a fresh, never-seen test each time (takes about 1 to 2 minutes to prepare)'+(aiOk?'':' <i>(AI not available here)</i>')+'</span></label><label class="opt"><input type="radio" name="msrc" value="bank" '+(aiOk?'':'checked')+'> <span><b>Built-in Mock Test</b>: ready instantly; speaking and writing questions are drawn at random from the bank</span></label>'+
 '<h3>2. Choose what to sit</h3><label class="opt"><input type="radio" name="scope" value="1" checked> <span><b>Part 1 only: Speaking and Writing</b> (about 75 minutes; best for your focus areas)</span></label><label class="opt"><input type="radio" name="scope" value="all"> <span><b>Full test</b> (about 2 hours 15 minutes)</span></label><label class="opt"><input type="radio" name="scope" value="2"> <span>Part 2 only: Reading (30 minutes)</span></label><label class="opt"><input type="radio" name="scope" value="3"> <span>Part 3 only: Listening (about 40 minutes)</span></label>'+
 '<h3>3. Before you start</h3><ul><li>Use headphones, sit somewhere quiet, and set up <a href="#settings">voice capture</a>.</li><li>Have a notepad ready, or use the on-screen noteboard.</li><li>Turn dictation <b>on</b> for speaking and <b>off</b> before the writing tasks.</li></ul><button class="btn primary" id="go">Start mock test</button></section>');
 $('#go').onclick=()=>startMock($('input[name=msrc]:checked').value,$('input[name=scope]:checked').value);}
async function buildMock(src,scope,onStep){const parts=scope==='all'?[1,2,3]:[+scope];const want={};parts.forEach(p=>ORDER[p].forEach(c=>want[c]=MOCK_COUNTS[c]));
 const got={};if(src==='ai'){const groups=[];if(parts.includes(1)){groups.push({RA:6,RS:10,ASQ:5,DI:5});groups.push({RL:2,RTS:2,SGD:2,SWT:2,WE:1});}if(parts.includes(2))groups.push({RFIBD:5,RMCMA:2,RO:2,RFIBDD:4,RMCSA:2});if(parts.includes(3))groups.push({SST:1,LMCMA:2,LFIB:2,HCS:2,LMCSA:2,SMW:1,HIW:2,WFD:3});
  let done=0,failed=0;onStep&&onStep(0,groups.length);const one=async g=>{try{const r=await generate(g);Object.assign(got,r);}catch(e){failed++;}done++;onStep&&onStep(done,groups.length);};
  await one(groups[0]);if(groups.length>1)await Promise.all(groups.slice(1).map(one));if(failed)toast(failed+' section(s) could not be generated, so built-in questions fill the gap.');}
 const items=[];let fallback=0;parts.forEach(p=>{items.push({type:'INTRO',part:p});ORDER[p].forEach(c=>{const n=want[c];let arr=(got[c]||[]).slice(0,n).map(x=>Object.assign(prep(x,c),{_src:'ai'}));if(arr.length<n){fallback+=n-arr.length;arr=arr.concat(c==='PI'?[{type:'PI'}]:bankPick(c,n-arr.length));}arr.forEach(x=>items.push(x));});});
 items.forEach((it,i)=>{it.id=it.id||(it.type+'-'+i);it._voice=it._voice||Math.floor(Math.random()*12);});return{items,fallback};}
async function startMock(src,scope){const run=newRun();setView('<section class="card center"><h1>Preparing your test</h1><div class="loading"><span class="spin"></span> <span id="prog">'+(src==='ai'?'Writing a brand new paper...':'Loading...')+'</span></div><p class="hint">AI papers take about 1 to 2 minutes. Meanwhile: breathe slowly, put on headphones, and open your dictation.</p></section>',true);
 const {items,fallback}=await buildMock(src,scope,(d,n)=>{const p=$('#prog');if(p)p.textContent='Writing a brand new paper... '+d+' of '+n+' sections ready';});if(!alive(run))return;if(src==='ai'&&fallback)toast(fallback+' questions came from the built-in bank.');
 MOCK={items,i:0,resp:{},scope:scope==='all'?'Full test':PART_NAMES[scope],run,clock:{},block:PENDING_MOCK_BLOCK};PENDING_MOCK_BLOCK=null;mockShow();}
function mockShell(){const it=MOCK.items[MOCK.i];const real=MOCK.items.filter(x=>x.type!=='INTRO'&&x.type!=='PI');const pos=real.indexOf(it)+1;
 return'<div class="exam-top"><span class="brand-s">PTE Academic · practice</span><span class="exam-meta">'+(it.type==='INTRO'?esc(PART_NAMES[it.part]):(pos?'Question '+pos+' of '+real.length:'Introduction'))+'</span><span class="exam-clock" id="eclock"></span></div><div class="exam-body"><div class="exam-task">'+(it.type!=='INTRO'?esc(T[it.type].name):'')+'</div><div class="card stage" id="stage"></div></div><div class="exam-foot"><button class="btn ghost xs" id="quit">Quit test</button><button class="btn primary" id="next">Next</button></div>';}
function mockShow(){const run=RUNID;MOCK.run=run;const it=MOCK.items[MOCK.i];setView(mockShell(),true);const stage=$('#stage');updateClock();
 $('#quit').onclick=()=>{const q=$('#quit');if(q.dataset.armed){finishMock(true);}else{q.dataset.armed=1;q.textContent='Click again: end and score now';}};
 if(it.type==='INTRO'){stage.innerHTML=introHTML(it.part);$('#next').textContent='Begin';$('#next').onclick=()=>{beep(660,0.05);startClockFor(it.part);mockAdvance();};if(it.part===1){$('#capPanel').hidden=false;$('#cap').placeholder='Start your dictation here now and check it types your words.';}return;}
 const ctl=mount(it,stage,{mode:'mock',run,onComplete(){},onTimeUp(){mockAdvance(ctl);}});MOCK.ctl=ctl;$('#next').onclick=()=>mockAdvance(ctl);
 if(WRITE.has(it.type)&&MOCK.items[MOCK.i-1]&&SPEAK.has(MOCK.items[MOCK.i-1].type)&&it.type!=='SST')toast('Writing tasks start now: turn OFF dictation and type your answer.');
 ctl.start();}
function introHTML(p){if(p===1)return'<h2>Part 1: Speaking and Writing</h2><p>This part has a personal introduction, then Read Aloud, Repeat Sentence, Describe Image, Retell Lecture, Answer Short Question, Respond to a Situation and Summarize Group Discussion, followed by Summarize Written Text and Write Essay. Each item has its own timer.</p><div class="note"><b>Voice capture:</b> click in the answer box at the bottom of the screen and start your dictation now (Windows: Win + H; Mac: Fn twice; phone: keyboard microphone). Say a few words to check it works. Keep it running for all speaking items: the app only keeps what you say after each recording beep. If it switches off, restart it when the recording begins.</div>';
 if(p===2)return'<h2>Part 2: Reading</h2><p>You have <b>30 minutes</b> for this part, shown in the top right. Reading and Writing Fill in the Blanks, Multiple Choice (multiple answers), Re-order Paragraphs, Fill in the Blanks (drag), Multiple Choice (single answer). Unanswered questions score zero, so answer everything.</p>';
 return'<h2>Part 3: Listening</h2><p>Each recording plays once. Summarize Spoken Text has its own 10-minute timer; the remaining questions share a <b>25-minute</b> clock. Take notes on the noteboard or paper.</p>';}
function startClockFor(part){clearSectionClock();if(part===2)runSectionClock(30*60,2);}
function runSectionClock(sec,part){const end=Date.now()+sec*1000;MOCK.clock={end,part};SECTION_IV=setInterval(()=>{updateClock();if(Date.now()>=MOCK.clock.end){clearSectionClock();toast('Time is up for this part.');skipRestOfPart(part);}},500);updateClock();}
function updateClock(){const el=$('#eclock');if(!el||!MOCK||!MOCK.clock.end){if(el)el.textContent='';return;}const left=(MOCK.clock.end-Date.now())/1000;el.innerHTML='Time remaining <b>'+fmt(left)+'</b>';el.classList.toggle('low',left<120);}
function skipRestOfPart(part){if(MOCK.ctl){MOCK.resp[MOCK.items[MOCK.i].id]=MOCK.ctl.collect();MOCK.ctl.destroy();MOCK.ctl=null;}let i=MOCK.i+1;while(i<MOCK.items.length&&MOCK.items[i].type!=='INTRO')i++;MOCK.i=i;MOCK.clock={};newRun();if(MOCK.i>=MOCK.items.length)return finishMock();mockShow();}
function mockAdvance(ctl){const it=MOCK.items[MOCK.i];if(ctl){MOCK.resp[it.id]=ctl.collect();ctl.destroy();MOCK.ctl=null;}
 if(it.type==='SST'&&!MOCK.clock.end){newRun();MOCK.i++;runSectionClock(25*60,3);if(MOCK.i>=MOCK.items.length)return finishMock();return mockShow();}
 const runKeep=MOCK.clock.end?MOCK.clock:null;RUNID++;stopAudio();stopSR();MOCK.i++;
 const nx=MOCK.items[MOCK.i];if(!nx||nx.type==='INTRO'){clearSectionClock();MOCK.clock={};}
 if(MOCK.i>=MOCK.items.length)return finishMock();mockShow();}
async function finishMock(early){const run=newRun();if(MOCK.ctl){try{MOCK.resp[MOCK.items[MOCK.i].id]=MOCK.ctl.collect();MOCK.ctl.destroy();}catch(e){}}
 setView('<section class="card center"><h1>Test complete</h1><div class="loading"><span class="spin"></span> <span id="prog">Scoring your answers...</span></div><p class="hint">Speaking and writing answers are being marked by your AI examiner. This can take up to a minute.</p></section>',true);
 const items=MOCK.items.filter(x=>x.type!=='INTRO');const res={};items.forEach(it=>{res[it.id]=scoreLocal(it,MOCK.resp[it.id]||{});});
 const open=items.filter(it=>OPEN.has(it.type)&&respText(MOCK.resp[it.id]).trim());let aiUsed=false;
 if(open.length&&AI==='ready'){try{const m=await aiMark(open.map(it=>({item:it,resp:MOCK.resp[it.id]})),t=>{const e=$('#prog');if(e)e.textContent=t;});open.forEach(it=>{if(m[it.id]){res[it.id]=fromAI(it,MOCK.resp[it.id],m[it.id]);aiUsed=true;}});}catch(e){toast('AI marking failed, offline estimates used: '+e.message);}}
 if(!alive(run))return;if(STANDALONE){DB.pendingMocks=DB.pendingMocks||[];DB.pendingMocks.push({t:Date.now(),scope:MOCK.scope,block:MOCK.block||null,items:JSON.parse(JSON.stringify(items)),resp:JSON.parse(JSON.stringify(MOCK.resp))});}else items.forEach(it=>{if(res[it.id])logAttempt(it.type,res[it.id].pct,MOCK.imported?'mock-import':'mock');});save();updateAIBadge();
 const scores=skillScores(items,res);
 DB.mocks.push({t:Date.now(),scope:MOCK.scope,scores,provisional:STANDALONE||undefined});save();
 const byType={};items.forEach(it=>{const r=res[it.id];if(!r)return;(byType[it.type]=byType[it.type]||[]).push(r.pct);});
 const tt=Object.keys(byType).map(c=>({c,avg:byType[c].reduce((a,b)=>a+b,0)/byType[c].length,n:byType[c].length}));const weak=tt.slice().sort((a,b)=>a.avg-b.avg).slice(0,3);
 const big=['Overall','Listening','Reading','Speaking','Writing'].filter(k=>scores[k]!=null).map(k=>'<div class="score'+(k==='Overall'?' ov':'')+'"><b>'+scores[k]+'</b><span>'+k+'</span><small>IELTS approx. '+ielts(k,scores[k])+'</small></div>').join('');
 const review=items.filter(it=>res[it.id]||it.type==='PI').map((it,i)=>'<details class="rv"><summary><span>'+esc(T[it.type].name)+'</span>'+(res[it.id]?pctTag(res[it.id].pct):'<small>not scored</small>')+'</summary>'+itemRecap(it)+renderFeedback(it,MOCK.resp[it.id]||{},res[it.id])+'</details>').join('');
 setView((STANDALONE?'<section class="card note bad"><h2 style="margin-top:0">Provisional report</h2><p>Reading, listening, Read Aloud, Repeat Sentence and Write from Dictation are marked exactly. Describe Image, Retell Lecture, Respond to a Situation, Summarize Group Discussion and all writing tasks need the <b>PTE-style AI marking</b>, which runs in claude.ai.</p><button class="btn primary" data-go="export">Get the AI-marked PTE report</button></section>':'')+(MOCK.imported?'<section class="card note"><b>AI-marked report</b> for the mock you sat on the Chrome site.</section>':'')+'<section class="card report"><p class="eyebrow">'+esc(MOCK.scope)+(early?' · ended early':'')+'</p><h1>Your estimated scores</h1><div class="scores">'+big+'</div><p class="hint">How these are calculated: every answer is marked on the official PTE trait scales (for example Content 0 to 6, Oral Fluency 0 to 5, Pronunciation 0 to 5), and each skill score is the share of available points you earned across all tasks feeding that skill, placed on the 10 to 90 scale. Integrated tasks count towards both their skills, as in the real test.'+(aiUsed?' Speaking and writing Content was '+(DB.settings.double!==false?'double-marked by two independent AI raters, with a senior rater deciding any disagreement of 2 or more points, mirroring Pearson\'s AI plus human check':'marked by an AI rater')+'.':' Open tasks use offline estimates.')+' Fluency and pronunciation are estimated from your transcript. IELTS equivalents use Pearson\'s July 2025 concordance table. Pearson does not publish its exact scaling, so treat these as practice estimates.</p></section>'+
 '<section class="card"><h2>Task breakdown</h2><div class="tablewrap"><table class="fmt"><thead><tr><th>Task</th><th>Items</th><th>Score</th><th></th></tr></thead><tbody>'+tt.map(x=>'<tr><td>'+esc(T[x.c].name)+'</td><td>'+x.n+'</td><td>'+pctTag(x.avg)+'</td><td><div class="tbar wide"><i style="width:'+Math.round(x.avg*100)+'%"></i></div></td></tr>').join('')+'</tbody></table></div></section>'+
 '<section class="card"><h2>Drill these next</h2><div class="tasks">'+weak.map(x=>'<button class="task focus" data-practise="'+x.c+'"><b>'+esc(T[x.c].name)+'</b><small>'+Math.round(x.avg*100)+'% this test</small></button>').join('')+'</div></section>'+
 '<section class="card"><h2>Your coach</h2>'+readiness(scores,'Your mock scores against your targets.')+'<div id="coachBox"><div class="loading"><span class="spin"></span> Writing your coaching report...</div></div></section><section class="card"><h2>Answer-by-answer review</h2>'+review+'</section><div class="row center">'+(MOCK.block?'<button class="btn primary" data-go="plan">Back to my plan</button>':'')+'<button class="btn '+(MOCK.block?'':'primary')+'" data-go="mock">Take another mock</button><button class="btn" data-go="home">Home</button></div>');
 renderNav('mock');document.body.classList.remove('exam');bindCommon();
 const mres=items.filter(it=>res[it.id]).map(it=>({type:it.type,pct:res[it.id].pct,got:res[it.id].got,max:res[it.id].max,fixes:(res[it.id].fixes||[]).slice(0,2),summary:res[it.id].summary||'',traits:(res[it.id].traits||[]).map(t=>t.name+' '+t.score+'/'+t.max).join(', ')}));const mcomps=compsFrom(mres);
 const rec={t:Date.now(),kind:'mock',scores,comps:mcomps,results:mres,coach:null};if(MOCK.block){DB.plan.done[MOCK.block]=rec;save();}
 let c;try{if(AI!=='ready')throw 0;c=await coach('mock test',MOCK.scope,mcomps,mres,scores);}catch(e){c=offlineCoach(mcomps,mres);}rec.coach=c;if(MOCK.block)save();const box=$('#coachBox');if(box){box.innerHTML=compTable(mcomps)+coachHTML(c);bindCommon();}}
function itemRecap(it){switch(it.type){case 'RA':case 'WFD':case 'RS':return'<p class="recap">'+esc(it.text)+'</p>';case 'DI':return'<div class="recap">'+renderChart(it.chart)+'</div>';case 'RTS':return'<p class="recap">'+esc(it.situation)+'</p>';case 'WE':return'<p class="recap">'+esc(it.prompt)+'</p>';case 'ASQ':return'<p class="recap">'+esc(it.question)+'</p>';case 'SWT':return'<details><summary>Passage</summary><p class="recap">'+esc(it.text)+'</p></details>';case 'RMCMA':case 'RMCSA':case 'LMCMA':case 'LMCSA':return'<p class="recap">'+esc(it.question)+'</p>';}return'';}

// ---------- 5-DAY PLAN ----------
DB.plan=DB.plan||{};DB.plan.done=DB.plan.done||{};DB.plan.dayReports=DB.plan.dayReports||{};
function targets(){return Object.assign({},PLAN.targets,DB.plan.targets||{});}
function isoDate(d){d=d||new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function daysToTest(){return Math.round((new Date(PLAN.testDate+'T00:00')-new Date(isoDate()+'T00:00'))/864e5);}
function needPct(t){return Math.min(100,Math.round((t-10)/80*100));}
function typeNeed(c){const tg=targets();return Math.max(...T[c].skills.map(s=>needPct(tg[s]||65)));}
function estSkills(list){const per={};list.forEach(a=>{(per[a.type]=per[a.type]||[]).push(a.pct/100);});const sk={Listening:[0,0],Reading:[0,0],Speaking:[0,0],Writing:[0,0]};
 Object.keys(per).forEach(c=>{if(!T[c]||!TYPICAL_POINTS[c])return;const arr=per[c].slice(-8);const avg=arr.reduce((a,b)=>a+b,0)/arr.length;const w=TYPICAL_POINTS[c]*(MOCK_COUNTS[c]||1);T[c].skills.forEach(s=>{sk[s][0]+=avg*w;sk[s][1]+=w;});});
 const out={};Object.keys(sk).forEach(k=>{if(sk[k][1])out[k]=Math.round(10+80*sk[k][0]/sk[k][1]);});return out;}
