async function coach(kind,title,comps,results,est){const tg=targets();
 const prompt='You are an expert PTE Academic coach. The student\'s test is on Monday 9 November 2026 ('+Math.max(0,daysToTest())+' days away). Targets: Speaking '+tg.Speaking+', Writing '+tg.Writing+', Reading '+tg.Reading+', Listening '+tg.Listening+'. Current estimated scores: '+JSON.stringify(est)+'. Below are results from the '+kind+' "'+title+'": for each task type, the % of points earned, the % needed for the target, and the examiner\'s main fixes from each attempt. Write a short, direct, honest and encouraging coaching report. Be specific to the evidence; name exact habits to change. Use Australian spelling. Do not use em dashes or en dashes.\nReturn ONLY JSON: {"headline":"one sentence overall verdict","components":[{"type":"task code","mark_comment":"one sentence on what this mark means against the target","improve":["2 or 3 specific actions"]}],"priorities":["the 3 most important things to fix before the next session"],"drill_next":["task codes to drill next"]}\n\nDATA:\n'+JSON.stringify({components:comps.map(c=>({type:c.type,name:T[c.type].name,items:c.n,percent:c.pct,needed_percent:c.need})),attempts:results.slice(-40).map(r=>({type:r.type,percent:Math.round(r.pct*100),traits:r.traits,verdict:r.summary,fixes:r.fixes}))});
 return await ask(prompt,'default');}
function offlineCoach(comps,results){const comp=comps.map(c=>{const fx=[];results.filter(r=>r.type===c.type).forEach(r=>(r.fixes||[]).forEach(f=>{if(fx.length<3&&!fx.includes(f))fx.push(f);}));return{type:c.type,mark_comment:c.pct>=c.need?'On target for your goal.':'About '+(c.need-c.pct)+' percentage points below what your target needs.',improve:fx.length?fx:['Repeat this task type and compare with the model answer.']};});
 const weak=comps.slice().sort((a,b)=>(a.pct-a.need)-(b.pct-b.need)).slice(0,3);return{headline:'Offline summary: AI coaching is unavailable right now.',components:comp,priorities:weak.map(w=>'Raise '+T[w.type].name+' from '+w.pct+'% towards '+w.need+'%.'),drill_next:weak.map(w=>w.type)};}
function coachHTML(c){if(!c)return'';return'<div class="coach"><p class="verdict">'+esc(c.headline||'')+'</p>'+(c.priorities&&c.priorities.length?'<h4>Fix these first</h4><ol>'+c.priorities.map(p=>'<li>'+esc(p)+'</li>').join('')+'</ol>':'')+(c.components||[]).filter(x=>T[x.type]).map(x=>'<div class="ccomp"><b>'+esc(T[x.type].name)+'</b> <span class="hint">'+esc(x.mark_comment||'')+'</span><ul>'+(x.improve||[]).map(i=>'<li>'+esc(i)+'</li>').join('')+'</ul></div>').join('')+(c.drill_next&&c.drill_next.length?'<div class="row">'+c.drill_next.filter(x=>T[x]).map(x=>'<button class="btn xs" data-practise="'+x+'">Drill '+esc(T[x].name)+'</button>').join('')+'</div>':'')+'</div>';}
