 if(results){const comps=compsFrom(results);rec={t:Date.now(),kind:'drill',comps,est:estSkills(results.map(r=>({type:r.type,pct:Math.round(r.pct*100)}))),results:results.map(r=>({at:r.at,partial:r.partial,type:r.type,pct:r.pct,got:r.got,max:r.max,fixes:r.fixes,summary:r.summary,traits:r.traits})),coach:null};DB.plan.done[id]=rec;save();}
